(async()=>{
 const checks=[],check=(ok,name)=>{checks.push({name,pass:Boolean(ok)});if(!ok)throw Error(name)},wait=()=>new Promise(r=>setTimeout(r,250)),saved=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1'));
 const click=async(label,root=document)=>{const el=[...root.querySelectorAll('button,a')].find(el=>el.textContent.trim()===label);check(el,'Control '+label);el.click();await wait();};
 const choose=async(label,text,root)=>{root.querySelector(`[role=combobox][aria-label="${label}"]`).click();await wait();const option=[...document.querySelectorAll('[role=option]')].find(el=>el.textContent.includes(text));check(option,'Option '+text);option.click();await wait();};
 location.hash='/p/launch/work-items/W-105?tab=brief';await wait();await click('确认计划 v1');await click('确认工作流版本');await click('分派Agent执行');const form=document.querySelector('dialog[open]');await choose('已分派的Agent','Atlas',form);await choose('匹配Runtime的在线节点','Codex CLI',form);await click('创建派发记录，等待节点接受',form);
 const e=saved().executions.find(e=>e.workId==='W-105');check(e?.kind==='AUTONOMOUS'&&e.state==='CREATED'&&e.initiatorKind==='SYSTEM','Work start creates an autonomous pending execution');check(saved().work.find(w=>w.id==='W-105').status==='待开始','No invented node acceptance');const start=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='分派Agent执行');check(start&&start.disabled,'Repeated dispatch blocked with exact pending result');check([...document.querySelectorAll('a')].some(a=>a.target==='_blank'&&a.getAttribute('href').includes(e.id)),'Pending execution has precise new-tab link');
 location.hash=`/chat?execution_id=${e.id}`;await wait();await click('模拟节点接受并启动');const dialog=document.querySelector('dialog[open]'),field=dialog.querySelector('textarea');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(field,'Explicit local node acceptance');field.dispatchEvent(new Event('input',{bubbles:true}));await wait();await click('模拟节点接受并启动',dialog);check(saved().work.find(w=>w.id==='W-105').status==='进行中','Node acceptance advances work atomically');check(![...document.querySelectorAll('button')].some(b=>b.textContent==='模拟工具授权请求'),'Codex does not imply Web tool permission');check(saved().executions.find(row=>row.id===e.id).workSnapshot.previewResources.length===0,'No inherited fabricated output');check(document.documentElement.scrollWidth<=innerWidth,'No viewport overflow');return {pass:true,width:innerWidth,checks,executionId:e.id};
})()
